.pk{--paper:#fff;--ink:#000;--link:#0000ee;--visited:#551a8b;--flash:#ff2e88;--teal:#00b3a4;--orange:#ff5c1a;--acid:#ffe600;
  background:var(--paper);color:var(--ink);
  font:400 15px/1.45 ui-monospace,'Courier New',Courier,monospace}
[data-theme=dark].pk,[data-theme=dark] .pk{--paper:#000;--ink:#fff;--link:#6f9bff;--visited:#c9a0ff}
.stage.pk{--page:var(--paper);background:var(--paper)}
.pk h3,.pk h4{margin:0;font-weight:700;text-transform:uppercase;line-height:.9;letter-spacing:-.02em}
.pk p{margin:0}
.pk a{color:var(--link);text-decoration:underline}
.pk a:visited{color:var(--visited)}
.box{border:3px solid var(--ink);padding:14px}
.blk{background:var(--ink);color:var(--paper);padding:8px 10px;display:inline-block}
.hr{border:0;border-top:3px solid var(--ink);margin:0}
.pk-btn{font:700 14px/1 inherit;text-transform:uppercase;background:var(--paper);color:var(--ink);
  border:3px solid var(--ink);border-radius:0;padding:12px 18px;cursor:pointer}
.pk-btn:hover{background:var(--ink);color:var(--paper)}
.pk-btn:focus-visible{outline:3px solid var(--flash);outline-offset:0}
.pk-btn.flash{background:var(--flash);color:#000;border-color:var(--ink)}
.pk-btn[disabled]{color:#767676;border-color:#767676;cursor:not-allowed}
.f-hover{background:var(--ink)!important;color:var(--paper)!important}
.f-focus{outline:3px solid var(--flash);outline-offset:0}
.pk-field{width:100%;background:var(--paper);color:var(--ink);border:3px solid var(--ink);
  border-radius:0;padding:10px;font:400 15px/1.2 inherit}
.pk-field:focus-visible{outline:3px solid var(--flash);outline-offset:0}
.pk-label{display:block;font-weight:700;text-transform:uppercase;font-size:13px;margin-bottom:5px}
.pk-err{margin-top:8px;background:var(--ink);color:var(--flash);padding:7px 9px;font-weight:700;font-size:13px}
.pk-nav{display:flex;gap:18px;flex-wrap:wrap;align-items:baseline;border-bottom:3px solid var(--ink);
  padding-bottom:8px}
.pk-nav a{padding:5px 0;display:inline-block;min-height:24px}
.pk-nav .sp{flex:1}
table.pk-t{width:100%;border-collapse:collapse;font-size:14px;border:3px solid var(--ink)}
table.pk-t th,table.pk-t td{border:1px solid var(--ink);padding:8px 10px;text-align:left}
table.pk-t th{background:var(--ink);color:var(--paper);text-transform:uppercase;font-size:12px}
.pk-scrim{background:rgba(0,0,0,.85);padding:32px 16px;display:flex;justify-content:center}
.pk-dialog{background:var(--paper);border:3px solid var(--ink);padding:20px;max-width:380px;width:100%}
.pk-empty{border:3px dashed var(--ink);padding:22px}
.pk-skel{height:14px;background:var(--ink);margin-bottom:9px}
.swatch{border:3px solid var(--ink);height:54px}
.mq{border-block:3px solid var(--ink);overflow:hidden;white-space:nowrap;padding:8px 0;
  font-weight:700;text-transform:uppercase}
/* ── raw field colours. Every one carries INK, never white. ─────────────── */
.field{padding:18px;border:3px solid var(--ink);color:#000}
.f-teal{background:var(--teal)}.f-orange{background:var(--orange)}
.f-pink{background:var(--flash)}.f-acid{background:var(--acid)}

/* ── hard-edged texture. Stripes and halftone, never a fade. ────────────── */
.stripe{background-image:repeating-linear-gradient(45deg,var(--ink) 0 6px,transparent 6px 12px)}
.halftone{background-image:radial-gradient(var(--ink) 1.6px,transparent 1.7px);
  background-size:9px 9px}

/* ── collage: overlap and negative margins, not a grid ──────────────────── */
.over{margin-top:-34px;margin-left:44px}
.under{margin-top:-22px;margin-right:60px}
.huge{font-size:clamp(2.6rem,12vw,9rem);line-height:.82;letter-spacing:-.04em;
  text-transform:uppercase;font-weight:700}
.stretch{transform:scaleY(1.28);transform-origin:left bottom;display:inline-block}
